// product_topology.go — the topology on the product of two spaces. A set
// of pairs is open when each of its points lies in a rectangle of two open
// sets inside it; so the open rectangles are a base, the product's points
// are the pairs of points, and a rectangle of closed sets is closed. The
// product of two topologies is a topology, generated by the open rectangles
// and by the cylinders of the two projections. The closure and the interior
// of a rectangle are the rectangles of the closures and of the interiors,
// and the product of two subspaces is the subspace on the rectangle.

package product_topology

import (
	. "github.com/euc-ai/xugo/library/authoring"
	"github.com/euc-ai/xugo/library/proofs/sets/functions"
	"github.com/euc-ai/xugo/library/proofs/sets/set_basic"
	"github.com/euc-ai/xugo/library/proofs/sets/set_image"
	"github.com/euc-ai/xugo/library/proofs/sets/set_order"
	"github.com/euc-ai/xugo/library/proofs/sets/set_product"
	"github.com/euc-ai/xugo/library/proofs/topology/topological_space"
	"github.com/euc-ai/xugo/library/registry"
)

// ---------------------------------------------------------------------------
// The open sets
// ---------------------------------------------------------------------------

// ProductOpenIff — a set of pairs is open exactly when each of its
// points lies in an open rectangle inside it.
var ProductOpenIff = productOpenIffThm{family.Add(registry.ProofEntry{
	Name: "ProductOpenIff",
	Key:  "prop_c108b95a0fdee68d",
	Reading: "product_topology is defined pointwise, so this and everything read through " +
		"it — rectangles open, the product's points, the projections continuous, closed " +
		"rectangles — holds for arbitrary families T and S; the axioms of T and S enter where " +
		"a proof meets two rectangles about one point (ProductTopology), reads a factor " +
		"pointwise (SliceRightContinuous) or takes a whole space as an open set (TubeLemma).",
	Build: family.Theorem("∀T:set(set(A)). ∀S:set(set(B)). ∀w:set(prod(A, B)). "+
		"    w ∈ product_topology(T, S) ⇔ "+
		"    ∀p:prod(A, B). "+
		"        p ∈ w ⇒ ∃u:set(A). ∃v:set(B). u ∈ T ∧ v ∈ S ∧ p ∈ set_cross(u, v) ∧ set_cross(u, v) ⊆ w",
		func(a *Argument, T *Expr[Set[Set[A]]], S *Expr[Set[Set[B]]], w *Expr[Set[Prod[A, B]]]) {
			a.Show(
				"membership in the family is the condition it is built from",
				Unfold(ProductTopologyDef),
				BySets())
		}),
})}

// RectangleOpen — a rectangle of two open sets is open.
var RectangleOpen = rectangleOpenThm{family.Add(registry.ProofEntry{
	Name: "RectangleOpen",
	Key:  "prop_2081d8bcbcb27d3a",
	Build: family.Theorem(Statement{
		Binders: "∀T:set(set(A)). ∀S:set(set(B)). ∀u:set(A). ∀v:set(B).",
		Hypotheses: []string{
			"u ∈ T",
			"v ∈ S",
		},
		Conclusion: "set_cross(u, v) ∈ product_topology(T, S)",
	},
		func(
			a *Argument,
			T *Expr[Set[Set[A]]],
			S *Expr[Set[Set[B]]],
			u *Expr[Set[A]],
			v *Expr[Set[B]],
			sides Fact,
		) {
			a.Do(Simp(Fwd(ProductOpenIff)))
			a.FixAs[Prod[A, B]]("p")
			point := a.Assume()
			a.Take(u)
			a.Take(v)
			a.Show(
				"the rectangle is the rectangle about each of its points",
				By(sides, point, set_order.SubsetRefl))
		}),
})}

// ProductSpace — the points of the product are the pairs of points.
var ProductSpace = productSpaceThm{family.Add(registry.ProofEntry{
	Name: "ProductSpace",
	Key:  "prop_23f2980e14ab8da5",
	Build: family.Theorem("∀T:set(set(A)). ∀S:set(set(B)). ⋃product_topology(T, S) = set_cross(⋃T, ⋃S)",
		func(a *Argument, T *Expr[Set[Set[A]]], S *Expr[Set[Set[B]]]) {
			a.Do(Simp(Fwd(set_basic.Extension.Inst[Prod[A, B]]())))
			p := a.FixAs[Prod[A, B]]("p")
			a.Iff()
			a.Forward(
				"a point of an open set lies in a rectangle of open "+
					"sets, so its projections are points of the spaces",
				func(b *Argument, point Fact) {
					w, open := b.ObtainAs[Set[Prod[A, B]]](
						"p lies in an open set of the product",
						"∃w:set(prod(A, B)). w ∈ product_topology(T, S) ∧ p ∈ w",
						By(point, set_basic.InUnions))
					_, _, rectangle := b.Obtain2(
						"that open set holds a rectangle of open sets about p",
						"∃u:set(A). ∃v:set(B). u ∈ T ∧ v ∈ S ∧ p ∈ set_cross(u, v) ∧ set_cross(u, v) ⊆ w",
						By(open, ProductOpenIff.At(T, S, w)))
					b.Show(
						"the sides of the rectangle hold the projections of p, and they are open",
						BySets(rectangle, set_product.InCrossProjections))
				})
			a.Backward(
				"a pair of points lies in the rectangle of an open set about each, which is open",
				func(b *Argument, point Fact) {
					u, first := b.ObtainAs[Set[A]](
						"the first projection lies in an open set",
						"∃u:set(A). u ∈ T ∧ fst(p) ∈ u",
						By(point, set_basic.InUnions, set_product.InCrossProjections))
					v, second := b.ObtainAs[Set[B]](
						"the second projection lies in an open set",
						"∃v:set(B). v ∈ S ∧ snd(p) ∈ v",
						By(point, set_basic.InUnions, set_product.InCrossProjections))
					b.Do(Simp(Fwd(set_basic.InUnions)))
					b.Take(b.TermAs[Set[Prod[A, B]]]("set_cross(u, v)"))
					b.Show(
						"the rectangle of u and v is open and holds p",
						By(first, second, RectangleOpen.At(T, S, u, v), set_product.InCrossProjections.At(u, v, p)))
				})
		}),
})}

// ProductTopology — the product of two topologies is a topology.
var ProductTopology = productTopologyThm{family.Add(registry.ProofEntry{
	Name: "ProductTopology",
	Key:  "prop_b3f94be5981ed44d",
	Build: family.Theorem(Statement{
		Binders: "∀T:set(set(A)). ∀S:set(set(B)).",
		Hypotheses: []string{
			"is_topology(T)",
			"is_topology(S)",
		},
		Conclusion: "is_topology(product_topology(T, S))",
	},
		func(a *Argument, T *Expr[Set[Set[A]]], S *Expr[Set[Set[B]]], topologies Fact) {
			spaces := a.Conjuncts(
				topologies,
				"T is a topology",
				"S is a topology")
			a.Do(Simp(Fwd(topological_space.IsTopology)), SplitConj(
				Case(
					"two open sets meet in an open set: the rectangles "+
						"about a common point meet in the rectangle of the meets",
					Simp(Fwd(ProductOpenIff)),
					Derive(func(b *Argument) {
						b.FixAs[Set[Prod[A, B]]]("w₁")
						b.FixAs[Set[Prod[A, B]]]("w₂")
						open := b.Conjuncts(
							b.Assume(),
							"each point of w₁ lies in a rectangle of open sets inside w₁",
							"each point of w₂ lies in a rectangle of open sets inside w₂")
						p := b.FixAs[Prod[A, B]]("p")
						inBoth := b.Assume()
						u1, v1, first := b.Obtain2As[Set[A], Set[B]](
							"w₁ gives p a rectangle of open sets inside it",
							"∃u:set(A). ∃v:set(B). u ∈ T ∧ v ∈ S ∧ p ∈ set_cross(u, v) ∧ set_cross(u, v) ⊆ w₁",
							BySets(open[0].At(p), inBoth),
							Named("u₁", "v₁"))
						u2, v2, second := b.Obtain2As[Set[A], Set[B]](
							"and w₂ gives it another inside w₂",
							"∃u:set(A). ∃v:set(B). u ∈ T ∧ v ∈ S ∧ p ∈ set_cross(u, v) ∧ set_cross(u, v) ⊆ w₂",
							BySets(open[1].At(p), inBoth),
							Named("u₂", "v₂"))
						b.Take(b.TermAs[Set[A]]("u₁ ∩ u₂"))
						b.Take(b.TermAs[Set[B]]("v₁ ∩ v₂"))
						b.Show(
							"the sides of the rectangle of the meets are open, and it is the meet of the two rectangles",
							BySets(
								first,
								second,
								topological_space.InterOpen.Read(spaces[0]).AsFact().At(u1, u2),
								topological_space.InterOpen.Read(spaces[1]).AsFact().At(v1, v2),
								set_product.CrossInter.At(u1, u2, v1, v2)))
					})),
				Case(
					"a union of open sets is open: a point keeps the rectangle its own member gives it",
					Simp(Fwd(ProductOpenIff)),
					Derive(func(b *Argument) {
						b.FixAs[Set[Set[Prod[A, B]]]]("s")
						opens := b.Assume()
						b.FixAs[Prod[A, B]]("p")
						point := b.Assume()
						w, member := b.ObtainAs[Set[Prod[A, B]]](
							"p lies in a member of the family",
							"∃w:set(prod(A, B)). w ∈ s ∧ p ∈ w",
							By(point, set_basic.InUnions))
						u, v, rectangle := b.Obtain2As[Set[A], Set[B]](
							"that member is open, so it gives p a rectangle of open sets inside it",
							"∃u:set(A). ∃v:set(B). u ∈ T ∧ v ∈ S ∧ p ∈ set_cross(u, v) ∧ set_cross(u, v) ⊆ w",
							By(opens, member, ProductOpenIff.At(T, S, w), set_basic.SubsetDef))
						b.Take(u)
						b.Take(v)
						b.Show(
							"the rectangle lies in the union, as the member holding it does",
							BySets(member, rectangle))
					})),
			))
		}),
})}

// ProductInducedGenerated — the product topology is generated on the product
// carrier by the two projection-induced families: their opens are cylinders,
// and every open rectangle is an intersection of two such cylinders.
var ProductInducedGenerated = productInducedGeneratedThm{family.Add(registry.ProofEntry{
	Name: "ProductInducedGenerated",
	Key:  "prop_54cb84ec3f78504",
	Build: family.Theorem(Statement{
		Binders: "∀T:set(set(A)). ∀S:set(set(B)).",
		Hypotheses: []string{
			"is_topology(T)",
			"is_topology(S)",
		},
		Conclusion: "product_topology(T, S) = " +
			"topology_generated_on(set_cross(⋃T, ⋃S), " +
			"    induced_topology(set_cross(⋃T, ⋃S), T, fst) ∪ induced_topology(set_cross(⋃T, ⋃S), S, snd))",
	},
		func(a *Argument, T *Expr[Set[Set[A]]], S *Expr[Set[Set[B]]], topologies Fact) {
			spaces := a.Conjuncts(
				topologies,
				"T is a topology",
				"S is a topology")
			X, carrier := a.LetAs[Set[Prod[A, B]]]("X", "set_cross(⋃T, ⋃S)")
			G, generators := a.LetAs[Set[Set[Prod[A, B]]]](
				"G", "induced_topology(X, T, fst) ∪ induced_topology(X, S, snd)")
			generated := a.Let("H", a.TermAs[Set[Set[Prod[A, B]]]]("topology_generated_on(X, G)"))
			product := a.TermAs[Set[Set[Prod[A, B]]]]("product_topology(T, S)")
			firstSpace := a.TermAs[Set[A]]("⋃T")
			secondSpace := a.TermAs[Set[B]]("⋃S")
			projectionMembership := set_product.InCrossProjections.Inst(
				TypeBinder.BindA[A](), TypeBinder.BindB[B]())
			setExt := set_basic.Extension.Inst[Prod[A, B]]()

			firstCylinder := a.Have(
				"the first projection gives a cylinder",
				"∀u:set(A). u ∈ T ⇒ preimage_on(X, fst, u) = set_cross(u, ⋃S)",
				Derive(func(b *Argument) {
					b.FixAs[Set[A]]("u")
					open := b.Assume()
					b.Do(Unfold(functions.PreimageOnDef), Simp(Fwd(setExt)))
					b.FixAs[Prod[A, B]]("p")
					b.Show(
						"membership is determined by the first coordinate",
						carrier.Rw(),
						Simp(Fwd(projectionMembership)),
						BySets(open))
				}))
			secondCylinder := a.Have(
				"the second projection gives a cylinder",
				"∀v:set(B). v ∈ S ⇒ preimage_on(X, snd, v) = set_cross(⋃T, v)",
				Derive(func(b *Argument) {
					b.FixAs[Set[B]]("v")
					open := b.Assume()
					b.Do(Unfold(functions.PreimageOnDef), Simp(Fwd(setExt)))
					b.FixAs[Prod[A, B]]("p")
					b.Show(
						"membership is determined by the second coordinate",
						carrier.Rw(),
						Simp(Fwd(projectionMembership)),
						BySets(open))
				}))
			firstSpaceOpen := a.Have(
				"the first space is open",
				"⋃T ∈ T",
				By(topological_space.SpaceOpen.Read(spaces[0])))
			secondSpaceOpen := a.Have(
				"the second space is open",
				"⋃S ∈ S",
				By(topological_space.SpaceOpen.Read(spaces[1])))
			firstOpen := a.Have(
				"first cylinders are product-open",
				"∀u:set(A). u ∈ T ⇒ preimage_on(X, fst, u) ∈ product_topology(T, S)",
				Derive(func(b *Argument) {
					u := b.FixAs[Set[A]]("u")
					open := b.Assume()
					rectangle := b.Have(
						"the cylinder rectangle is open",
						"set_cross(u, ⋃S) ∈ product_topology(T, S)",
						By(open, secondSpaceOpen, RectangleOpen.At(T, S, u, secondSpace)))
					b.Show(
						"the restricted preimage is that rectangle",
						By(Normalized, rectangle, open, firstCylinder.At(u)))
				}))
			secondOpen := a.Have(
				"second cylinders are product-open",
				"∀v:set(B). v ∈ S ⇒ preimage_on(X, snd, v) ∈ product_topology(T, S)",
				Derive(func(b *Argument) {
					v := b.FixAs[Set[B]]("v")
					open := b.Assume()
					rectangle := b.Have(
						"the cylinder rectangle is open",
						"set_cross(⋃T, v) ∈ product_topology(T, S)",
						By(open, firstSpaceOpen, RectangleOpen.At(T, S, firstSpace, v)))
					b.Show(
						"the restricted preimage is that rectangle",
						By(Normalized, rectangle, open, secondCylinder.At(v)))
				}))
			generatorsOpen := a.Have(
				"both projection families lie in the product topology",
				"G ⊆ product_topology(T, S)",
				generators.Rw(),
				Unfold(topological_space.InducedTopologyDef),
				Simp(Fwd(set_order.UnionSubset.Inst[Set[Prod[A, B]]]())),
				SplitConj(
					Case(
						"every first projection preimage is open",
						Simp(Fwd(set_basic.SubsetDef.Inst[Set[Prod[A, B]]]())),
						Simp(
							Fwd(set_image.ForallInImage.Inst(TypeBinder.BindA[Set[A]](), TypeBinder.BindB[Set[Prod[A, B]]]()))),
						By(firstOpen)),
					Case(
						"every second projection preimage is open",
						Simp(Fwd(set_basic.SubsetDef.Inst[Set[Prod[A, B]]]())),
						Simp(
							Fwd(set_image.ForallInImage.Inst(TypeBinder.BindA[Set[B]](), TypeBinder.BindB[Set[Prod[A, B]]]()))),
						By(secondOpen)),
				))
			productTopology := a.Have(
				"the product is a topology",
				"is_topology(product_topology(T, S))",
				By(spaces[0], spaces[1], ProductTopology.At(T, S)))
			productSpace := a.Have(
				"its carrier is X",
				"⋃product_topology(T, S) = X",
				By(Normalized, carrier, ProductSpace.At(T, S)))
			minimal := a.Have(
				"generation stays inside the product topology",
				"H ⊆ product_topology(T, S)",
				generated.Rw(),
				By(
					productTopology,
					productSpace,
					generatorsOpen,
					topological_space.GeneratedOnMinimal.At(X, product, G)))
			generatedTopology := a.Have(
				"H is a topology",
				"is_topology(H)",
				generated.Rw(),
				By(topological_space.GeneratedOnTopology))
			contains := a.Have(
				"H contains its generators",
				"G ⊆ H",
				generated.Rw(),
				By(topological_space.GeneratedOnContains))

			rectanglesOpen := a.Have(
				"open rectangles lie in H",
				"∀u:set(A). ∀v:set(B). u ∈ T ∧ v ∈ S ⇒ set_cross(u, v) ∈ H",
				Derive(func(b *Argument) {
					u := b.FixAs[Set[A]]("u")
					v := b.FixAs[Set[B]]("v")
					sides := b.Conjuncts(
						b.Assume(),
						"the first side is open",
						"the second side is open")
					firstPullback := b.TermAs[Fun[Set[A], Set[Prod[A, B]]]]("preimage_on(X, fst)")
					secondPullback := b.TermAs[Fun[Set[B], Set[Prod[A, B]]]]("preimage_on(X, snd)")
					firstGenerator := b.Have(
						"the first cylinder belongs to the first induced family",
						"preimage_on(X, fst, u) ∈ induced_topology(X, T, fst)",
						Unfold(topological_space.InducedTopologyDef),
						By(sides[0], set_image.FunInImage.At(firstPullback, T, u)))
					firstInH := b.Have(
						"the first cylinder is open in H",
						"preimage_on(X, fst, u) ∈ H",
						BySets(generators, contains, firstGenerator))
					secondGenerator := b.Have(
						"the second cylinder belongs to the second induced family",
						"preimage_on(X, snd, v) ∈ induced_topology(X, S, snd)",
						Unfold(topological_space.InducedTopologyDef),
						By(sides[1], set_image.FunInImage.At(secondPullback, S, v)))
					secondInH := b.Have(
						"the second cylinder is open in H",
						"preimage_on(X, snd, v) ∈ H",
						BySets(generators, contains, secondGenerator))
					meetOpen := b.Have(
						"the two cylinders have an open intersection",
						"preimage_on(X, fst, u) ∩ preimage_on(X, snd, v) ∈ H",
						By(
							firstInH,
							secondInH,
							topological_space.InterOpen.Read(generatedTopology).AsFact().At(
								b.TermAs[Set[Prod[A, B]]]("preimage_on(X, fst, u)"),
								b.TermAs[Set[Prod[A, B]]]("preimage_on(X, snd, v)"))))
					meet := b.Have(
						"their intersection is the rectangle",
						"set_cross(u, v) = preimage_on(X, fst, u) ∩ preimage_on(X, snd, v)",
						Unfold(functions.PreimageOnDef),
						Simp(Fwd(setExt)),
						Derive(func(c *Argument) {
							c.FixAs[Prod[A, B]]("p")
							c.Show(
								"both coordinates satisfy the rectangle conditions",
								carrier.Rw(),
								Simp(Fwd(projectionMembership)),
								BySets(sides[0], sides[1]))
						}))
					b.Show(
						"the rectangle is open in H",
						By(meet, meetOpen))
				}))
			productIncluded := a.Have(
				"every product-open set is open in H",
				"product_topology(T, S) ⊆ H",
				Simp(Fwd(set_basic.SubsetDef.Inst[Set[Prod[A, B]]]())),
				Derive(func(b *Argument) {
					w := b.FixAs[Set[Prod[A, B]]]("w")
					open := b.Assume()
					b.Do(Cite(topological_space.OpenPointwise.Read(generatedTopology), w))
					pointwiseCriterion := b.Hyp(
						"w ∈ H ⇔ ∀p:prod(A, B). p ∈ w ⇒ ∃r:set(prod(A, B)). r ∈ H ∧ r ⊆ w ∧ p ∈ r")
					locallyOpen := b.Have(
						"each point has a rectangle open in H inside w",
						"∀p:prod(A, B). p ∈ w ⇒ ∃r:set(prod(A, B)). r ∈ H ∧ r ⊆ w ∧ p ∈ r",
						Derive(func(c *Argument) {
							c.FixAs[Prod[A, B]]("p")
							point := c.Assume()
							u, v, rectangle := c.Obtain2As[Set[A], Set[B]](
								"the product-open neighbourhood contains an open rectangle",
								"∃u:set(A). ∃v:set(B). u ∈ T ∧ v ∈ S ∧ p ∈ set_cross(u, v) ∧ set_cross(u, v) ⊆ w",
								By(open, point, ProductOpenIff.At(T, S, w)),
								Named("u", "v"))
							c.Take(c.TermAs[Set[Prod[A, B]]]("set_cross(u, v)").Core())
							c.Show(
								"the rectangle supplies the required neighbourhood",
								By(rectangle, rectanglesOpen.At(u, v)))
						}))
					b.Show(
						"the pointwise criterion gives openness",
						By(locallyOpen, pointwiseCriterion))
				}))
			a.Show(
				"the two families of opens coincide",
				By(minimal, productIncluded, set_order.SubsetAntisym))
		}),
})}

// ---------------------------------------------------------------------------
// Closed rectangles
// ---------------------------------------------------------------------------

// ClosedRectangle — a rectangle of two closed sets is closed.
var ClosedRectangle = closedRectangleThm{family.Add(registry.ProofEntry{
	Name: "ClosedRectangle",
	Key:  "prop_f9392f5685ae9bf3",
	Deps: []registry.EntryLike{
		ProductSpace,
		ProductOpenIff,
		set_product.CrossDifference,
		set_product.InCrossProjections,
	},
	Build: family.Card(Statement{
		Binders: "∀T:set(set(A)). ∀S:set(set(B)). ∀c:set(A). ∀d:set(B).",
		Hypotheses: []string{
			"closed_in(T, c)",
			"closed_in(S, d)",
		},
		Conclusion: "closed_in(product_topology(T, S), set_cross(c, d))",
	},
		"The rectangle lies in the product's points (ProductSpace). Its complement there "+
			"is two rectangles (set_product.CrossDifference), the complement of c against "+
			"the second space and the first space against the complement of d; a point of "+
			"either lies in the rectangle of the open complement and an open set about its "+
			"other projection, inside the complement (ProductOpenIff). No axiom enters."),
})}
